1	package tariff
2	
3	import (
4		"errors"
5		"math"
6		"sort"
7		"sync"
8		"time"
9	)
10	
11	// 登记费率版本时可能返回的错误。
12	var (
13		ErrEmptyItemID            = errors.New("tariff: item id must not be empty")
14		ErrEmptyVersionID         = errors.New("tariff: version id must not be empty")
15		ErrInvalidUnitPrice       = errors.New("tariff: unit price must not be negative")
16		ErrStartRequired          = errors.New("tariff: effective start time is required")
17		ErrInvalidInterval        = errors.New("tariff: end time must be after start time")
18		ErrVersionExists          = errors.New("tariff: version id already registered for the item")
19		ErrOverlap                = errors.New("tariff: version interval overlaps an existing version of the item")
20		ErrReplaceTargetNotFound  = errors.New("tariff: replaced version does not exist")
21		ErrReplaceTargetWrongItem = errors.New("tariff: replaced version belongs to another item")
22		ErrInvalidReplacement     = errors.New("tariff: new version start must be after the replaced version start and within its current effective interval")
23	)
24	
25	// 查询与报价时可能返回的错误。
26	var (
27		ErrItemNotFound      = errors.New("tariff: rate item not found")
28		ErrRequestNotFound   = errors.New("tariff: request id not found")
29		ErrRequestIDConflict = errors.New("tariff: request id already used with different content")
30	)
31	
32	// RejectReason 区分报价被拒绝的原因。
33	type RejectReason string
34	
35	const (
36		ReasonNone                   RejectReason = ""
37		ReasonEmptyRequestID         RejectReason = "empty_request_id"
38		ReasonInvalidQuantity        RejectReason = "invalid_quantity"
39		ReasonVersionNotFound        RejectReason = "version_not_found"
40		ReasonVersionNotYetEffective RejectReason = "version_not_yet_effective"
41		ReasonVersionExpired         RejectReason = "version_expired"
42		ReasonTotalOverflow          RejectReason = "total_overflow"
43	)
44	
45	// RegisterRequest 描述一次费率版本登记。
46	type RegisterRequest struct {
47		ItemID    string
48		VersionID string
49		UnitPrice int64      // 整数分单价，可以为零，不能为负
50		Start     time.Time  // 必填，生效时刻（含）
51		End       *time.Time // 可选，结束时刻（不含）；nil 表示持续有效
52		Replaces  string     // 可选，同项内被本版本替代的旧版本标识
53	}
54	
55	// VersionView 是查询费率项时返回的版本视图，
56	// 同时包含登记的起止时间、替代关系和实际有效区间。
57	type VersionView struct {
58		ItemID         string
59		VersionID      string
60		UnitPrice      int64
61		Start          time.Time  // 登记的生效时刻（含）
62		End            *time.Time // 登记的结束时刻（不含），nil 表示持续有效
63		Replaces       string     // 本版本登记时替代的旧版本，空表示无
64		SupersededBy   string     // 替代本版本的新版本，空表示未被替代
65		EffectiveStart time.Time  // 实际有效区间起点（含）
66		EffectiveEnd   *time.Time // 实际有效区间终点（不含），nil 表示持续有效
67	}
68	
69	// QuoteRequest 描述一次报价请求。
70	type QuoteRequest struct {
71		RequestID string // 非空请求标识，用于幂等与查询
72		ItemID    string
73		VersionID string
74		Quantity  int64 // 正整数
75	}
76	
77	// Outcome 是报价的首次受理结果：要么确认，要么带原因拒绝。
78	// 成功报价即为已确认记录，之后费率变化不会改写其中的金额和来源。
79	type Outcome struct {
80		Request    QuoteRequest // 原请求内容
81		AcceptedAt time.Time    // 首次受理时刻
82		Confirmed  bool
83		UnitPrice  int64        // 确认时的实际单价（分）
84		Total      int64        // 确认时的总价（分）
85		Reason     RejectReason // 被拒绝时的原因
86	}
87	
88	// version 是登记在册的费率版本。effEnd 因被替代而可能早于登记的 end。
89	type version struct {
90		itemID       string
91		versionID    string
92		unitPrice    int64
93		start        time.Time
94		end          *time.Time
95		replaces     string
96		supersededBy string
97		effEnd       *time.Time
98	}
99	
100	// Book 是费率版本与报价的本地账本，可并发使用。
101	type Book struct {
102		mu       sync.Mutex
103		now      func() time.Time
104		items    map[string]map[string]*version // itemID -> versionID -> version
105		requests map[string]Outcome             // requestID -> 首次受理结果
106	}
107	
108	// Option 定制 Book 的行为。
109	type Option func(*Book)
110	
111	// WithClock 指定受理时刻的来源，默认使用 time.Now。
112	func WithClock(now func() time.Time) Option {
113		return func(b *Book) {
114			if now != nil {
115				b.now = now
116			}
117		}
118	}
119	
120	// NewBook 返回一个空的账本。
121	func NewBook(opts ...Option) *Book {
122		b := &Book{
123			now:      time.Now,
124			items:    make(map[string]map[string]*version),
125			requests: make(map[string]Outcome),
126		}
127		for _, opt := range opts {
128			opt(b)
129		}
130		return b
131	}
132	
133	// RegisterVersion 登记一个费率版本。任何校验失败都不会留下部分变更。
134	func (b *Book) RegisterVersion(req RegisterRequest) error {
135		b.mu.Lock()
136		defer b.mu.Unlock()
137	
138		if req.ItemID == "" {
139			return ErrEmptyItemID
140		}
141		if req.VersionID == "" {
142			return ErrEmptyVersionID
143		}
144		if req.UnitPrice < 0 {
145			return ErrInvalidUnitPrice
146		}
147		if req.Start.IsZero() {
148			return ErrStartRequired
149		}
150		if req.End != nil && !req.End.After(req.Start) {
151			return ErrInvalidInterval
152		}
153	
154		versions := b.items[req.ItemID]
155		if _, ok := versions[req.VersionID]; ok {
156			return ErrVersionExists
157		}
158	
159		var target *version
160		if req.Replaces != "" {
161			t, ok := versions[req.Replaces]
162			if !ok {
163				if b.versionInOtherItem(req.ItemID, req.Replaces) {
164					return ErrReplaceTargetWrongItem
165				}
166				return ErrReplaceTargetNotFound
167			}
168			// 新版本的开始必须晚于旧版本的开始，且落在旧版本当前的有效区间内。
169			if !req.Start.After(t.start) {
170				return ErrInvalidReplacement
171			}
172			if t.effEnd != nil && !req.Start.Before(*t.effEnd) {
173				return ErrInvalidReplacement
174			}
175			target = t
176		}
177	
178		// 与同项其他版本的实际有效区间比较，不允许重叠；
179		// 被替代版本会被截断到新版本开始时刻，不参与重叠判断。
180		for _, v := range versions {
181			if v == target {
182				continue
183			}
184			if intervalsOverlap(req.Start, req.End, v.start, v.effEnd) {
185				return ErrOverlap
186			}
187		}
188	
189		// 全部校验通过后才提交变更。结束时刻必须复制后入库：
190		// 既不能与调用方的请求变量共享指针，登记结束与实际结束之间也互为独立副本，
191		// 外部对原变量或任一返回结果的修改都不能改写账本中的边界。
192		v := &version{
193			itemID:    req.ItemID,
194			versionID: req.VersionID,
195			unitPrice: req.UnitPrice,
196			start:     req.Start,
197			end:       cloneTimePtr(req.End),
198			replaces:  req.Replaces,
199			effEnd:    cloneTimePtr(req.End),
200		}
201		if target != nil {
202			truncated := req.Start
203			target.effEnd = &truncated
204			target.supersededBy = req.VersionID
205		}
206		if versions == nil {
207			versions = make(map[string]*version)
208			b.items[req.ItemID] = versions
209		}
210		versions[req.VersionID] = v
211		return nil
212	}
213	
214	func (b *Book) versionInOtherItem(itemID, versionID string) bool {
215		for id, versions := range b.items {
216			if id == itemID {
217				continue
218			}
219			if _, ok := versions[versionID]; ok {
220				return true
221			}
222		}
223		return false
224	}
225	
226	// cloneTimePtr 返回结束时刻的独立副本，nil 原样返回。
227	// time.Time 是值类型，但账本持有的是 *time.Time，必须复制指针指向的值，
228	// 否则调用方修改自己的时间变量就会改写账本。
229	func cloneTimePtr(t *time.Time) *time.Time {
230		if t == nil {
231			return nil
232		}
233		cp := *t
234		return &cp
235	}
236	
237	// intervalsOverlap 判断半开区间 [s1,e1) 与 [s2,e2) 是否重叠，nil 终点表示持续有效。
238	// 时间比较按实际时刻进行，不同时区偏移不影响结果。
239	func intervalsOverlap(s1 time.Time, e1 *time.Time, s2 time.Time, e2 *time.Time) bool {
240		if e1 != nil && !s2.Before(*e1) {
241			return false
242		}
243		if e2 != nil && !s1.Before(*e2) {
244			return false
245		}
246		return true
247	}
248	
249	// ItemVersions 返回费率项下各版本的登记信息与实际有效区间，按生效时刻排序。
250	func (b *Book) ItemVersions(itemID string) ([]VersionView, error) {
251		b.mu.Lock()
252		defer b.mu.Unlock()
253	
254		versions, ok := b.items[itemID]
255		if !ok || len(versions) == 0 {
256			return nil, ErrItemNotFound
257		}
258		views := make([]VersionView, 0, len(versions))
259		for _, v := range versions {
260			views = append(views, VersionView{
261				ItemID:         v.itemID,
262				VersionID:      v.versionID,
263				UnitPrice:      v.unitPrice,
264				Start:          v.start,
265				End:            cloneTimePtr(v.end),
266				Replaces:       v.replaces,
267				SupersededBy:   v.supersededBy,
268				EffectiveStart: v.start,
269				EffectiveEnd:   cloneTimePtr(v.effEnd),
270			})
271		}
272		sort.Slice(views, func(i, j int) bool {
273			if !views[i].EffectiveStart.Equal(views[j].EffectiveStart) {
274				return views[i].EffectiveStart.Before(views[j].EffectiveStart)
275			}
276			return views[i].VersionID < views[j].VersionID
277		})
278		return views, nil
279	}
280	
281	// Quote 按首次受理时刻判断指定版本是否有效并给出报价。
282	// 非空请求标识的首次结果（无论确认还是拒绝）都会被保存；
283	// 相同标识且业务内容相同的重试返回首次结果，内容不同则返回 ErrRequestIDConflict。
284	func (b *Book) Quote(req QuoteRequest) (Outcome, error) {
285		b.mu.Lock()
286		defer b.mu.Unlock()
287	
288		if req.RequestID == "" {
289			return Outcome{
290				Request:    req,
291				AcceptedAt: b.now(),
292				Reason:     ReasonEmptyRequestID,
293			}, nil
294		}
295	
296		if prev, ok := b.requests[req.RequestID]; ok {
297			same := prev.Request.ItemID == req.ItemID &&
298				prev.Request.VersionID == req.VersionID &&
299				prev.Request.Quantity == req.Quantity
300			if !same {
301				return Outcome{}, ErrRequestIDConflict
302			}
303			return prev, nil
304		}
305	
306		out := Outcome{Request: req, AcceptedAt: b.now()}
307		switch {
308		case req.Quantity <= 0:
309			out.Reason = ReasonInvalidQuantity
310		default:
311			v := b.items[req.ItemID][req.VersionID]
312			switch {
313			case v == nil:
314				out.Reason = ReasonVersionNotFound
315			case out.AcceptedAt.Before(v.start):
316				out.Reason = ReasonVersionNotYetEffective
317			case v.effEnd != nil && !out.AcceptedAt.Before(*v.effEnd):
318				out.Reason = ReasonVersionExpired
319			case v.unitPrice > 0 && req.Quantity > math.MaxInt64/v.unitPrice:
320				out.Reason = ReasonTotalOverflow
321			default:
322				out.Confirmed = true
323				out.UnitPrice = v.unitPrice
324				out.Total = v.unitPrice * req.Quantity
325			}
326		}
327		b.requests[req.RequestID] = out
328		return out, nil
329	}
330	
331	// Lookup 按请求标识查询保存的首次受理结果，未见过的标识返回 ErrRequestNotFound。
332	func (b *Book) Lookup(requestID string) (Outcome, error) {
333		b.mu.Lock()
334		defer b.mu.Unlock()
335	
336		out, ok := b.requests[requestID]
337		if !ok {
338			return Outcome{}, ErrRequestNotFound
339		}
340		return out, nil
341	}
