1	package tariff
2	
3	import (
4		"errors"
5		"math"
6		"sync"
7		"testing"
8		"time"
9	)
10	
11	var base = time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
12	
13	func at(hours int) time.Time { return base.Add(time.Duration(hours) * time.Hour) }
14	
15	func atPtr(hours int) *time.Time {
16		t := at(hours)
17		return &t
18	}
19	
20	// fixedClock 返回可手动推进的时钟。
21	func fixedClock(start time.Time) (func() time.Time, func(time.Time)) {
22		var mu sync.Mutex
23		cur := start
24		return func() time.Time {
25				mu.Lock()
26				defer mu.Unlock()
27				return cur
28			}, func(t time.Time) {
29				mu.Lock()
30				defer mu.Unlock()
31				cur = t
32			}
33	}
34	
35	func TestRegisterValidation(t *testing.T) {
36		b := NewBook()
37		ok := RegisterRequest{ItemID: "seat", VersionID: "v1", UnitPrice: 100, Start: at(0)}
38	
39		if err := b.RegisterVersion(RegisterRequest{VersionID: "v1", UnitPrice: 1, Start: at(0)}); !errors.Is(err, ErrEmptyItemID) {
40			t.Fatalf("empty item: %v", err)
41		}
42		if err := b.RegisterVersion(RegisterRequest{ItemID: "seat", UnitPrice: 1, Start: at(0)}); !errors.Is(err, ErrEmptyVersionID) {
43			t.Fatalf("empty version: %v", err)
44		}
45		r := ok
46		r.UnitPrice = -1
47		if err := b.RegisterVersion(r); !errors.Is(err, ErrInvalidUnitPrice) {
48			t.Fatalf("negative price: %v", err)
49		}
50		r = ok
51		r.UnitPrice = 0 // 零单价允许
52		if err := b.RegisterVersion(r); err != nil {
53			t.Fatalf("zero price should be allowed: %v", err)
54		}
55		r = ok
56		r.VersionID = "v2"
57		r.Start = time.Time{}
58		if err := b.RegisterVersion(r); !errors.Is(err, ErrStartRequired) {
59			t.Fatalf("missing start: %v", err)
60		}
61		r = ok
62		r.VersionID = "v2"
63		r.End = atPtr(0) // 结束必须晚于开始
64		if err := b.RegisterVersion(r); !errors.Is(err, ErrInvalidInterval) {
65			t.Fatalf("end == start: %v", err)
66		}
67		r.End = atPtr(-1)
68		if err := b.RegisterVersion(r); !errors.Is(err, ErrInvalidInterval) {
69			t.Fatalf("end < start: %v", err)
70		}
71		if err := b.RegisterVersion(ok); !errors.Is(err, ErrVersionExists) {
72			t.Fatalf("duplicate version id: %v", err)
73		}
74		// 相同版本标识可用于另一费率项
75		r = ok
76		r.ItemID = "room"
77		if err := b.RegisterVersion(r); err != nil {
78			t.Fatalf("same version id on another item: %v", err)
79		}
80	}
81	
82	func TestRegisterOverlapAndAdjacency(t *testing.T) {
83		b := NewBook()
84		must := func(r RegisterRequest) {
85			t.Helper()
86			if err := b.RegisterVersion(r); err != nil {
87				t.Fatalf("register %+v: %v", r, err)
88			}
89		}
90		must(RegisterRequest{ItemID: "seat", VersionID: "v1", UnitPrice: 1, Start: at(0), End: atPtr(10)})
91	
92		// 相邻交接（end == start）允许
93		must(RegisterRequest{ItemID: "seat", VersionID: "v2", UnitPrice: 1, Start: at(10)})
94	
95		overlaps := []RegisterRequest{
96			{ItemID: "seat", VersionID: "x1", UnitPrice: 1, Start: at(5), End: atPtr(15)},
97			{ItemID: "seat", VersionID: "x2", UnitPrice: 1, Start: at(-5), End: atPtr(1)},
98			{ItemID: "seat", VersionID: "x3", UnitPrice: 1, Start: at(5), End: atPtr(6)},
99			{ItemID: "seat", VersionID: "x4", UnitPrice: 1, Start: at(-5), End: atPtr(20)},
100			{ItemID: "seat", VersionID: "x5", UnitPrice: 1, Start: at(9)},
101		}
102		for _, r := range overlaps {
103			if err := b.RegisterVersion(r); !errors.Is(err, ErrOverlap) {
104				t.Fatalf("expected overlap for %+v, got %v", r, err)
105			}
106		}
107		// 重叠失败不留下部分变更
108		views, err := b.ItemVersions("seat")
109		if err != nil {
110			t.Fatal(err)
111		}
112		if len(views) != 2 {
113			t.Fatalf("failed registrations left changes behind: %d versions", len(views))
114		}
115		// 不同费率项互不影响
116		must(RegisterRequest{ItemID: "room", VersionID: "v1", UnitPrice: 1, Start: at(0), End: atPtr(10)})
117	}
118	
119	func TestRegisterTimezoneInstants(t *testing.T) {
120		b := NewBook()
121		// 同一时刻、不同时区偏移
122		startUTC := time.Date(2026, 3, 1, 10, 0, 0, 0, time.UTC)
123		endUTC := time.Date(2026, 3, 1, 20, 0, 0, 0, time.UTC)
124		if err := b.RegisterVersion(RegisterRequest{
125			ItemID: "seat", VersionID: "v1", UnitPrice: 1,
126			Start: startUTC, End: &endUTC,
127		}); err != nil {
128			t.Fatal(err)
129		}
130		// +08:00 的 18:00 即 UTC 10:00，与 v1 开始重叠，应被拒绝
131		east := time.FixedZone("UTC+8", 8*3600)
132		overlap := time.Date(2026, 3, 1, 18, 0, 0, 0, east)
133		if err := b.RegisterVersion(RegisterRequest{
134			ItemID: "seat", VersionID: "v2", UnitPrice: 1, Start: overlap,
135		}); !errors.Is(err, ErrOverlap) {
136			t.Fatalf("same instant in another offset must overlap: %v", err)
137		}
138		// +08:00 的 04:00(+1d) 即 UTC 20:00，恰好交接，允许
139		adjacent := time.Date(2026, 3, 2, 4, 0, 0, 0, east)
140		if err := b.RegisterVersion(RegisterRequest{
141			ItemID: "seat", VersionID: "v2", UnitPrice: 1, Start: adjacent,
142		}); err != nil {
143			t.Fatalf("adjacent handoff across offsets: %v", err)
144		}
145	}
146	
147	func TestReplacement(t *testing.T) {
148		now, setNow := fixedClock(at(0))
149		b := NewBook(WithClock(now))
150		must := func(r RegisterRequest) {
151			t.Helper()
152			if err := b.RegisterVersion(r); err != nil {
153				t.Fatalf("register %+v: %v", r, err)
154			}
155		}
156		must(RegisterRequest{ItemID: "seat", VersionID: "old", UnitPrice: 100, Start: at(0), End: atPtr(100)})
157		must(RegisterRequest{ItemID: "seat", VersionID: "new", UnitPrice: 200, Start: at(40), Replaces: "old"})
158	
159		views, err := b.ItemVersions("seat")
160		if err != nil {
161			t.Fatal(err)
162		}
163		if len(views) != 2 {
164			t.Fatalf("want 2 versions, got %d", len(views))
165		}
166		old, nv := views[0], views[1]
167		if old.VersionID != "old" || nv.VersionID != "new" {
168			t.Fatalf("unexpected order: %v, %v", old.VersionID, nv.VersionID)
169		}
170		// 登记信息保留，替代关系可见
171		if old.End == nil || !old.End.Equal(at(100)) {
172			t.Fatalf("registered end lost: %v", old.End)
173		}
174		if nv.Replaces != "old" || old.SupersededBy != "new" {
175			t.Fatalf("replacement relation missing: %+v %+v", old, nv)
176		}
177		// 实际有效区间：old 被截断到 new 的开始
178		if old.EffectiveEnd == nil || !old.EffectiveEnd.Equal(at(40)) {
179			t.Fatalf("old effective end: %v", old.EffectiveEnd)
180		}
181		if nv.EffectiveEnd != nil {
182			t.Fatalf("new should be open-ended: %v", nv.EffectiveEnd)
183		}
184	
185		// 新版本到期后，被替代的旧版本不会重新生效：
186		// 用另一个项验证——new 到期后 old 的有效区间仍止于交接点。
187		must(RegisterRequest{ItemID: "hall", VersionID: "old", UnitPrice: 1, Start: at(0), End: atPtr(100)})
188		must(RegisterRequest{ItemID: "hall", VersionID: "new", UnitPrice: 1, Start: at(40), End: atPtr(50), Replaces: "old"})
189		setNow(at(60)) // new 已到期
190		out, err := b.Quote(QuoteRequest{RequestID: "q-hall-old", ItemID: "hall", VersionID: "old", Quantity: 1})
191		if err != nil {
192			t.Fatal(err)
193		}
194		if out.Confirmed || out.Reason != ReasonVersionExpired {
195			t.Fatalf("superseded old version must not revive: %+v", out)
196		}
197		out, err = b.Quote(QuoteRequest{RequestID: "q-hall-new", ItemID: "hall", VersionID: "new", Quantity: 1})
198		if err != nil {
199			t.Fatal(err)
200		}
201		if out.Confirmed || out.Reason != ReasonVersionExpired {
202			t.Fatalf("expired new version: %+v", out)
203		}
204	}
205	
206	func TestReplacementRejected(t *testing.T) {
207		b := NewBook()
208		must := func(r RegisterRequest) {
209			t.Helper()
210			if err := b.RegisterVersion(r); err != nil {
211				t.Fatalf("register %+v: %v", r, err)
